+        }
+    }
+
+    fn serde_serialize<'py, S: serde::ser::Serializer>(
+        &self,
+        value: &Bound<'py, PyAny>,
+        serializer: S,
+        state: &mut SerializationState<'py>,
+    ) -> Result<S::Ok, S::Error> {
+        match state.extra.ob_type_lookup.is_type(value, ObType::Fraction) {
